Clear-Host; Write-Host "📡 Initializing Live Peer Connection HUD..." -ForegroundColor Cyan; Write-Host "🔍 Listening for inbound handshakes on 8080 & 8081..." -ForegroundColor Yellow; while ($true) { $Conns = Get-NetTCPConnection -LocalPort 8080, 8081 -State Established -ErrorAction SilentlyContinue | Where-Object { $_.RemoteAddress -ne "127.0.0.1" -and $_.RemoteAddress -ne "0.0.0.0" }; if ($Conns) { $Time = Get-Date -Format "HH:mm:ss"; foreach ($C in $Conns) { Write-Host "[$Time] 🛰️ Active Connection on Port $($C.LocalPort) from $($C.RemoteAddress):$($C.RemotePort)" -ForegroundColor Green } }; Start-Sleep -Seconds 2 }